// Characterization tests: pin CURRENT behaviour of order totals, quirks included.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.1, D: 100, E: 100.5, F: 33.33, G: 1000 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { return await fn(base) } finally { await new Promise((r) => server.close(r)) }
}

const post = (base, items) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ items }),
})

async function totalFor(items) {
  return withApp(async (base) => {
    const res = await post(base, items)
    assert.equal(res.status, 201)
    return (await res.json()).total
  })
}

const cases = [
  ['single item, no discount', [{ sku: 'A', qty: 1 }], 10],
  ['multiple lines summed', [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }], 71],
  ['fractional total is floored, not rounded', [{ sku: 'B', qty: 1 }], 25],
  ['total exactly 100 gets no discount', [{ sku: 'D', qty: 1 }], 100],
  ['10 x 10 = 100 gets no discount', [{ sku: 'A', qty: 10 }], 100],
  ['just over 100 (100.5) gets 10% off: 90.45 floored', [{ sku: 'E', qty: 1 }], 90],
  ['101 -> 90.9 floored to 90', [{ sku: 'A', qty: 10 }, { sku: 'C', qty: 10 }], 90],
  ['large order 1000 -> 900', [{ sku: 'G', qty: 1 }], 900],
  ['10% applies to the whole order, no tiers (5000 -> 4500)', [{ sku: 'G', qty: 5 }], 4500],
  ['no further discount for very large orders (100000 -> 90000)', [{ sku: 'G', qty: 100 }], 90000],
  ['floor after discount: 33.33*4=133.32 -> 119.988 -> 119', [{ sku: 'F', qty: 4 }], 119],
  ['qty 0 contributes nothing', [{ sku: 'G', qty: 0 }, { sku: 'A', qty: 1 }], 10],
]
for (const [name, items, expected] of cases) {
  test(`total: ${name}`, async () => assert.equal(await totalFor(items), expected))
}

test('quirk: negative qty is accepted and reduces the total (no validation)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 5 }, { sku: 'B', qty: -1 }]), 24)
})

test('quirk: unknown sku (price undefined) yields a null total', async () => {
  assert.equal(await totalFor([{ sku: 'ZZZ', qty: 1 }]), null)
})

test('created order is stored and retrievable with same total', async () => {
  await withApp(async (base) => {
    const created = await (await post(base, [{ sku: 'G', qty: 1 }])).json()
    assert.match(created.id, /^\d+$/)
    const got = await (await fetch(`${base}/orders/${created.id}`)).json()
    assert.deepEqual(got, created)
    assert.deepEqual(created.items, [{ sku: 'G', qty: 1 }])
  })
})

test('validation: missing/empty items -> 400', async () => {
  await withApp(async (base) => {
    for (const body of ['{}', '{"items":[]}', 'not json']) {
      const res = await fetch(`${base}/orders`, { method: 'POST', body })
      assert.equal(res.status, 400)
      assert.deepEqual(await res.json(), { error: 'items required' })
    }
  })
})

test('quirk: unknown order id returns 200 with error body (not 404)', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders/999`)
    assert.equal(res.status, 200)
    assert.deepEqual(await res.json(), { error: 'not found' })
  })
})

test('unknown route -> 404', async () => {
  await withApp(async (base) => {
    const res = await fetch(`${base}/nope`)
    assert.equal(res.status, 404)
  })
})
EOF
